## rlx for Nim, over its C ABI (`librlx_capi`): every C function, generated by
## rlx-bindgen from rlx-bind's tables (`rlx/generated.nim`, included below),
## on the hand-written support here. The library is found on the platform's
## search path; `-d:rlxLib=<path>` names it.

import std/[algorithm, json, monotimes, options, tables, times]
export json, options, tables

const rlxLib* {.strdefine.} =
  when defined(macosx): "librlx_capi.dylib"
  elif defined(windows): "rlx_capi.dll"
  else: "librlx_capi.so"

const NONE* = 0xFFFFFFFF ## "No node", for an optional node argument.

type
  RlxErrorKind* = enum
    ekType = "type", ekRange = "range", ekRuntime = "runtime", ekPanic = "panic",
    ekNotFound = "not_found", ekOther = "other"
  RlxError* = object of CatchableError ## A failed rlx call.
    kind*: RlxErrorKind
  TypedTensor* = object ## A tensor of any dtype: little-endian bytes + dtype name.
    data*: seq[byte]
    dtype*: string
  RlxSlice {.bycopy.} = object
    p: pointer
    len: csize_t
  Keep = object ## C buffers for one call, freed when it returns.
    bufs: seq[pointer]
  Inputs = object
    names, data, lens, dtypes: pointer
    n: int

proc `=destroy`(k: Keep) =
  for p in k.bufs: dealloc(p)

proc c_rlx_last_error(): cstring {.importc: "rlx_last_error", dynlib: rlxLib, cdecl.}
proc c_rlx_string_free(s: pointer) {.importc: "rlx_string_free", dynlib: rlxLib, cdecl.}
proc c_rlx_f32s_release(v: ptr RlxSlice) {.importc: "rlx_f32s_release", dynlib: rlxLib, cdecl.}
proc c_rlx_bytes_release(v: ptr RlxSlice) {.importc: "rlx_bytes_release", dynlib: rlxLib, cdecl.}
proc c_rlx_u32s_release(v: ptr RlxSlice) {.importc: "rlx_u32s_release", dynlib: rlxLib, cdecl.}
proc c_rlx_outputs_len(o: pointer): csize_t {.importc: "rlx_outputs_len", dynlib: rlxLib, cdecl.}
proc c_rlx_outputs_get(o: pointer; i: csize_t; d: ptr pointer; n: ptr csize_t): int32 {.importc: "rlx_outputs_get", dynlib: rlxLib, cdecl.}
proc c_rlx_outputs_free(o: pointer) {.importc: "rlx_outputs_free", dynlib: rlxLib, cdecl.}
proc c_rlx_typed_outputs_len(o: pointer): csize_t {.importc: "rlx_typed_outputs_len", dynlib: rlxLib, cdecl.}
proc c_rlx_typed_outputs_get(o: pointer; i: csize_t; d: ptr pointer; n: ptr csize_t; dt: ptr cstring): int32 {.importc: "rlx_typed_outputs_get", dynlib: rlxLib, cdecl.}
proc c_rlx_typed_outputs_free(o: pointer) {.importc: "rlx_typed_outputs_free", dynlib: rlxLib, cdecl.}
proc c_rlx_tensor_map_len(m: pointer): csize_t {.importc: "rlx_tensor_map_len", dynlib: rlxLib, cdecl.}
proc c_rlx_tensor_map_get(m: pointer; i: csize_t; name: ptr cstring; d: ptr pointer; n: ptr csize_t): int32 {.importc: "rlx_tensor_map_get", dynlib: rlxLib, cdecl.}
proc c_rlx_tensor_map_free(m: pointer) {.importc: "rlx_tensor_map_free", dynlib: rlxLib, cdecl.}
proc c_rlx_optimizer_step(o: pointer; names: pointer; params: pointer; grads: pointer; lens: pointer; shapes: pointer; ndims: pointer; n: csize_t): int32 {.importc: "rlx_optimizer_step", dynlib: rlxLib, cdecl.}

proc check(rc: int32) =
  if rc != 0:
    let kind = case rc
      of -1: ekType
      of -2: ekRange
      of -3: ekRuntime
      of -4: ekPanic
      of -5: ekNotFound
      else: ekOther
    var e = newException(RlxError, $c_rlx_last_error())
    e.kind = kind
    raise e

# ── arguments ─────────────────────────────────────────────────

proc buf(k: var Keep; bytes: int): pointer =
  result = alloc0(max(bytes, 1))
  k.bufs.add result

proc arr[T, U](k: var Keep; v: openArray[U]): pointer =
  if v.len == 0: return nil
  result = k.buf(v.len * sizeof(T))
  let a = cast[ptr UncheckedArray[T]](result)
  for i, x in v: a[i] = T(x)

proc floats(k: var Keep; v: openArray[float]): pointer = arr[cfloat, float](k, v)
proc bytes(k: var Keep; v: openArray[byte]): pointer = arr[byte, byte](k, v)
proc u32s(k: var Keep; v: openArray[int]): pointer = arr[uint32, int](k, v)
proc u64s(k: var Keep; v: openArray[int]): pointer = arr[uint64, int](k, v)
proc i64s(k: var Keep; v: openArray[int]): pointer = arr[int64, int](k, v)

proc str(k: var Keep; s: string): cstring =
  let p = k.buf(s.len + 1)
  if s.len > 0: copyMem(p, unsafeAddr s[0], s.len)
  cast[cstring](p)

proc optStr(s: Option[string]): cstring =
  if s.isSome: cstring(s.get) else: nil

proc json(k: var Keep; v: JsonNode): cstring =
  if v.isNil: nil else: k.str($v)

proc boxU64(k: var Keep; v: Option[int]): pointer =
  if v.isNone: return nil
  result = k.buf(8)
  cast[ptr uint64](result)[] = uint64(v.get)

proc boxF32(k: var Keep; v: Option[float]): pointer =
  if v.isNone: return nil
  result = k.buf(4)
  cast[ptr cfloat](result)[] = cfloat(v.get)

proc strs(k: var Keep; v: openArray[string]): pointer =
  if v.len == 0: return nil
  result = k.buf(v.len * sizeof(cstring))
  let a = cast[ptr UncheckedArray[cstring]](result)
  for i, s in v: a[i] = k.str(s)

proc rows(v: openArray[seq[int]]; w: int; splat: bool): seq[int] =
  for i, r in v:
    if r.len == w: result.add r
    elif splat and r.len == 1:
      for _ in 0 ..< w: result.add r[0]
    else:
      var e = newException(RlxError, "row " & $i & " needs " & $w & " values, got " & $r.len)
      e.kind = ekType
      raise e

proc frows(v: openArray[seq[float]]; w: int): seq[float] =
  for i, r in v:
    if r.len != w:
      var e = newException(RlxError, "row " & $i & " needs " & $w & " values, got " & $r.len)
      e.kind = ekType
      raise e
    result.add r

proc inputs(k: var Keep; m: openArray[(string, seq[float])]): Inputs =
  var items = @m
  items.sort(proc (a, b: (string, seq[float])): int = cmp(a[0], b[0]))
  var names: seq[string]
  let n = items.len
  let data = cast[ptr UncheckedArray[pointer]](k.buf(n * sizeof(pointer)))
  let lens = cast[ptr UncheckedArray[csize_t]](k.buf(n * sizeof(csize_t)))
  for i, (name, v) in items:
    names.add name
    data[i] = k.floats(v)
    lens[i] = csize_t(v.len)
  Inputs(names: k.strs(names), data: data, lens: lens, n: n)

proc typedInputs(k: var Keep; m: openArray[(string, TypedTensor)]): Inputs =
  var items = @m
  items.sort(proc (a, b: (string, TypedTensor)): int = cmp(a[0], b[0]))
  var names, dtypes: seq[string]
  let n = items.len
  let data = cast[ptr UncheckedArray[pointer]](k.buf(n * sizeof(pointer)))
  let lens = cast[ptr UncheckedArray[csize_t]](k.buf(n * sizeof(csize_t)))
  for i, (name, t) in items:
    names.add name
    dtypes.add t.dtype
    data[i] = k.bytes(t.data)
    lens[i] = csize_t(t.data.len)
  Inputs(names: k.strs(names), data: data, lens: lens, dtypes: k.strs(dtypes), n: n)

# ── results ───────────────────────────────────────────────────

proc takeStringOpt(p: pointer): Option[string] =
  if p.isNil: return none(string)
  result = some($cast[cstring](p))
  c_rlx_string_free(p)

proc takeString(p: pointer): string = takeStringOpt(p).get("")

proc floatsAt(p: pointer; n: int): seq[float] =
  let a = cast[ptr UncheckedArray[cfloat]](p)
  for i in 0 ..< n: result.add float(a[i])

proc takeF32s(o: var RlxSlice): seq[float] =
  result = floatsAt(o.p, int(o.len))
  c_rlx_f32s_release(addr o)

proc takeBytes(o: var RlxSlice): seq[byte] =
  result = newSeq[byte](int(o.len))
  if o.len > 0: copyMem(addr result[0], o.p, int(o.len))
  c_rlx_bytes_release(addr o)

proc takeU32s(o: var RlxSlice): seq[int] =
  let a = cast[ptr UncheckedArray[uint32]](o.p)
  for i in 0 ..< int(o.len): result.add int(a[i])
  c_rlx_u32s_release(addr o)

proc takeOutputs(o: pointer): seq[seq[float]] =
  for i in 0 ..< int(c_rlx_outputs_len(o)):
    var d: pointer
    var n: csize_t
    discard c_rlx_outputs_get(o, csize_t(i), addr d, addr n)
    result.add floatsAt(d, int(n))
  c_rlx_outputs_free(o)

proc takeTypedOutputs(o: pointer): seq[TypedTensor] =
  for i in 0 ..< int(c_rlx_typed_outputs_len(o)):
    var d: pointer
    var n: csize_t
    var dt: cstring
    discard c_rlx_typed_outputs_get(o, csize_t(i), addr d, addr n, addr dt)
    var t = TypedTensor(data: newSeq[byte](int(n)), dtype: $dt)
    if n > 0: copyMem(addr t.data[0], d, int(n))
    result.add t
  c_rlx_typed_outputs_free(o)

proc takeTensors(m: pointer): Table[string, seq[float]] =
  for i in 0 ..< int(c_rlx_tensor_map_len(m)):
    var name: cstring
    var d: pointer
    var n: csize_t
    discard c_rlx_tensor_map_get(m, csize_t(i), addr name, addr d, addr n)
    result[$name] = floatsAt(d, int(n))
  c_rlx_tensor_map_free(m)

include rlx/generated

# ── the manual rows ───────────────────────────────────────────

proc step*(self: Optimizer; params: var Table[string, seq[float]]; grads: Table[string, seq[float]]) =
  ## Update each `params[name]` in place from `grads[name]`.
  var k: Keep
  var names: seq[string]
  for name in params.keys: names.add name
  names.sort()
  let n = names.len
  let ps = cast[ptr UncheckedArray[pointer]](k.buf(n * sizeof(pointer)))
  let gs = cast[ptr UncheckedArray[pointer]](k.buf(n * sizeof(pointer)))
  let lens = cast[ptr UncheckedArray[csize_t]](k.buf(n * sizeof(csize_t)))
  for i, name in names:
    if name notin grads:
      var e = newException(RlxError, "Optimizer.step: no gradient for '" & name & "'")
      e.kind = ekType
      raise e
    ps[i] = k.floats(params[name])
    gs[i] = k.floats(grads[name])
    lens[i] = csize_t(params[name].len)
  check c_rlx_optimizer_step(self.h, k.strs(names), ps, gs, lens, nil, nil, csize_t(n))
  for i, name in names:
    params[name] = floatsAt(ps[i], int(lens[i]))

type TrainSummary* = object ## What `Trainer.run` did.
  steps*: int
  stopped*: bool
  firstLoss*, lastLoss*, meanLoss*, gradNorm*: Option[float]
  stepsPerSecond*: float

proc run*(self: Trainer; steps: int; batch: proc (step: int): Option[seq[(string, seq[float])]];
          lr: proc (step: int): float = nil; onStep: proc (step: int; loss: float): bool = nil;
          every = 1): TrainSummary =
  ## Train `steps` steps, pulling inputs from `batch(step)` (none: data
  ## exhausted). `lr(step)` schedules the rate; `onStep(step, loss)` returning
  ## false stops early (called every `every` steps).
  let every = max(every, 1)
  let start = self.steps()
  var losses: seq[float]
  let t0 = getMonoTime()
  for i in 0 ..< steps:
    let s = start + i
    let b = batch(s)
    if b.isNone: break
    if lr != nil: self.setLr(lr(s))
    let loss = self.step(b.get)
    losses.add loss
    if onStep != nil and (i + 1) mod every == 0 and not onStep(s, loss):
      result.stopped = true
      break
  let secs = max((getMonoTime() - t0).inNanoseconds.float / 1e9, 1e-9)
  result.steps = losses.len
  if losses.len > 0:
    result.firstLoss = some(losses[0])
    result.lastLoss = some(losses[^1])
    var sum = 0.0
    for l in losses: sum += l
    result.meanLoss = some(sum / losses.len.float)
  result.stepsPerSecond = losses.len.float / secs
  result.gradNorm = self.gradNorm()
